local ECSComponent = import("Frame.ECS.ECSComponent")

---@class RoleStoryQuestComponent
local RoleStoryQuestComponent = Class("RoleStoryQuestComponent", ECSComponent)
local RoleQuestDojo = import("Game.Dojo.RoleQuestDojo")

function RoleStoryQuestComponent:__init()
    self._allOverFinaleId = {}     --所有的结局id
    self._allDrawRewardId = {}     --所有领取的奖励id
    self._challengeInfo = {}       --正在进行中的章节信息






    self._questInfo = {}               --关卡信息

    self._newChapter = {}              --新解锁的关卡  小红点判断用
    self._lastChapterId = nil            --上次战斗的关卡  界面缓存用
end

function RoleStoryQuestComponent:__delete()
    self._questInfo = nil               --关卡信息+
    self._newChapter = nil
    self._lastChapterId = nil            --上次战斗的关卡  界面缓存用
end

--
function RoleStoryQuestComponent:InitialRoleStoryCopy(jsonData)
    self._allOverFinaleId = {}     
    self._allDrawRewardId = {}   
    self._challengeInfo = {}
    if not jsonData then
        return 
    end

    local t = checkTable(jsonData.catQuestInfo)
    for k, v in pairs(t) do
        for _k, _v in pairs(checkTable(v.overFinaleIds)) do
            self._allOverFinaleId[checkString(_v)] = 1
        end

        for _k, _v in pairs(checkTable(v.drawFinaleIds)) do
            self._allDrawRewardId[checkString(_v)] = 1
        end
    end

    t = checkTable(jsonData.currentChapterInfo)
    for k, v in pairs(t) do
        self._challengeInfo[checkString(k)] = v
    end
end

--回退
function RoleStoryQuestComponent:BackQuestReq(questId, chapterId, cb)
    GameUtils.Request(Interfaces.CatQuestBackQuest, {questId = questId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end

        local jsonData = response.data
        if not self._challengeInfo then
            self._challengeInfo = {}
        end
        self._challengeInfo[checkString(chapterId)] = jsonData.currentChapterInfo

        if cb then
            cb()
        end
    end)
end

--是否完成了结局
function RoleStoryQuestComponent:IsHasOverFinaleId(overFinaleId)
    if checkNumber(overFinaleId) <= 0 then
        return
    end
    if not self._allOverFinaleId then
        return
    end
    return (checkNumber(self._allOverFinaleId[checkString(overFinaleId)]) == 1)
end

--是否领取了奖励
function RoleStoryQuestComponent:IsDrawRewardId(rewardId)
    if checkNumber(rewardId) <= 0 then
        return
    end
    if not self._allDrawRewardId then
        return
    end
    return (checkNumber(self._allDrawRewardId[checkString(rewardId)]) == 1)
end

