---@param questId string 关卡id 
function RoleStoryQuestComponent:IsUnlockQuestById(questId)
    if checkNumber(questId) == 0 then
        return true
    end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return false
    end

    local t = CfUtils.Split(vo.unlockNum1)

    if #t == 1 and checkNumber(t[1]) == 0 then
        return true
    end
    --[[
    local isPass = self:IsPassQuestById(vo.unlockNum1)
    local isFeelingEnough = false
    if checkNumber(vo.unlockType) == 0 then
        isFeelingEnough = true
    elseif checkNumber(vo.unlockType) == 1 then  --大于
        isFeelingEnough = (checkNumber(self.GetFellingNum(vo.stageID)) > checkNumber(vo.unlockNum2))
    elseif checkNumber(vo.unlockType) == 2 then  --小于
        isFeelingEnough = (checkNumber(self.GetFellingNum(vo.stageID)) < checkNumber(vo.unlockNum2))
    elseif checkNumber(vo.unlockType) == 3 then  --等于
        isFeelingEnough = (checkNumber(self.GetFellingNum(vo.stageID)) == checkNumber(vo.unlockNum2))
    end

    return isPass and isFeelingEnough
    ]]

    local t = self._challengeInfo[checkString(vo.stageID)]
    if not t then
        return false
    end
    for k, v in pairs(checkTable(t.unlockQuestIds)) do
        if checkNumber(v) == checkNumber(questId) then
            return true
        end
    end
    return false
end

---IsPassQuestById 是否通关关卡
---@param questId string 关卡id 
function RoleStoryQuestComponent:IsPassQuestById(questId)
    if checkNumber(questId) == 0 then
        return true
    end
    questId = checkString(questId)
    if not self._challengeInfo then
        return false
    end

    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return false
    end
    local t = self._challengeInfo[checkString(vo.stageID)]
    if not t then
        return false
    end
    for k, v in pairs(t.chapterIds) do
        if checkNumber(v) == checkNumber(questId) then
            return true
        end
    end
    return false
end

--获取该章节已解锁的关卡
function RoleStoryQuestComponent:GetUnlockQuestIds(chapterId)
    if not self._challengeInfo then
        return {}
    end
    local t = self._challengeInfo[checkString(chapterId)]
    if not t then
        return {}
    end
    return checkTable(t.unlockQuestIds)
end

--当前章节的心情值
function RoleStoryQuestComponent:GetFellingNum(chapterId)
    if not self._challengeInfo then
        return 0
    end
    local t = self._challengeInfo[checkString(chapterId)]
    if not t then
        return 0
    end
    return checkNumber(t.mood)
end

--该章节上一次通关的节点id
function RoleStoryQuestComponent:GetLastChallengeQuestId(chapterId)
    if not self._challengeInfo then
        return 0
    end
    local t = self._challengeInfo[checkString(chapterId)]
    if not t then
        return 0
    end
    return checkNumber(t.newPassedQuestId)
end

---DrawRewardReq 领取奖励
---@param rewardId string 奖励id
function RoleStoryQuestComponent:DrawRewardReq(rewardId, cb)
    GameUtils.Request(Interfaces.CatQuestDrawReward, {id = checkString(rewardId)}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            local rewards = responseData.rewards
            GoodsUtils.DrawRewards(rewards, true)
            CS.Engine.UI.UIModule.OpenDialog({id = Constants.UITypeIds.UICommonRewardPop, parameters = {rewards = clone(rewards)}})
            self._allDrawRewardId[checkString(rewardId)] = 1
            
            if cb then
                cb()
            end
            Events.Broadcast(Constants.EventNames.RedpointDataChange, nil)
        end
    end)
end

--放弃章节
function RoleStoryQuestComponent:QuitChapterReq(chapterId, cb)
    GameUtils.Request(Interfaces.CatQuestQuitChapter, {chapterId = checkString(chapterId)}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            if self._challengeInfo then
                self._challengeInfo[checkString(chapterId)] = nil
            end
            
            if cb then
                cb()
            end
        end
    end)
end

---StoryEnterReq 看完剧情
---@param questId string 关卡id
function RoleStoryQuestComponent:StoryEnterReq(questId, mood, optionIds, cb)
    mood = checkNumber(mood)
    optionIds = checkString(optionIds)
    GameUtils.Request(Interfaces.CatQuestPlot, {questId = checkNumber(questId), mood = mood, plotIds = optionIds}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            self:UpdateRoleQuestInfo(questId)

            local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
            if self._challengeInfo then
                if self._challengeInfo[checkString(vo.stageID)] then
                    self._challengeInfo[checkString(vo.stageID)].mood = checkNumber(self._challengeInfo[checkString(vo.stageID)].mood) + mood
                    self._challengeInfo[checkString(vo.stageID)].unlockQuestIds = checkTable(responseData.unlockQuestIds)
                    self._challengeInfo[checkString(vo.stageID)].newPassedQuestId = checkNumber(questId)
                end
            end
            if cb then
                cb()
            end
        end
    end)
end

--更新关卡信息
function RoleStoryQuestComponent:UpdateRoleQuestInfo(questId)
    questId = checkNumber(questId)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById((questId))
    if vo then
        if not self._challengeInfo then
            self._challengeInfo = {}
        end

        if not self._challengeInfo[checkString(vo.stageID)] then
            self._challengeInfo[checkString(vo.stageID)] = {}
        end

        if isNull(self._challengeInfo[checkString(vo.stageID)].chapterIds) then
            self._challengeInfo[checkString(vo.stageID)].chapterIds = {}
        end
        table.insert(self._challengeInfo[checkString(vo.stageID)].chapterIds, questId)

        if checkNumber(vo.finale) == 1 then
            local cgId = QuestConfMgr:GetInstance():GetOverFinaleCgIdByQuestId(questId)
            if checkNumber(cgId) > 0 then 
                self._allOverFinaleId[checkString(cgId)] = 1
            end
        end
    end
    CS.Engine.Lib.KCookie.Set("RoleStoryPassQuest", questId)
end

return RoleStoryQuestComponent